from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        forb = set(forbidden)
        maxlen = 10
        for w in forbidden:
            if len(w) > maxlen:
                maxlen = len(w)
        n = len(word)
        left = 0
        best = 0
        for r in range(n):
            # find the largest start l (>= left) such that word[l..r] is forbidden
            lowest = max(left, r - maxlen + 1)
            for l in range(r, lowest - 1, -1):
                if word[l:r + 1] in forb:
                    left = l + 1
                    break
            if r - left + 1 > best:
                best = r - left + 1
        return best
