class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        forb = set(forbidden)
        n = len(word)
        left = 0
        best = 0
        for r in range(n):
            # check all substrings ending at r with length up to 10
            lo = max(left, r - 9)
            for l in range(lo, r + 1):
                if word[l:r + 1] in forb:
                    left = l + 1
                    break
            # Since we want the smallest valid start, the largest forbidden start
            # ending at r determines left; iterate to find the maximal such l.
            # The loop above breaks at the first (smallest l) forbidden substring,
            # so recompute to get the largest l among forbidden substrings ending at r.
            new_left = left
            for l in range(max(left, r - 9), r + 1):
                if word[l:r + 1] in forb:
                    if l + 1 > new_left:
                        new_left = l + 1
            left = new_left
            if r - left + 1 > best:
                best = r - left + 1
        return best
